package app.dayflow;
import org.json.*;
import java.time.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Explicit mapping to the existing TaskFlow v2 tables. Unknown Android fields survive. */
final class TaskFlowRecords {
    private static final Set<String> TRANSPORT=new HashSet<>(Arrays.asList("revision","ancestors","updated_at","conflict_of"));
    static String canonical(Object value)throws JSONException{if(value==null||value==JSONObject.NULL)return "null";if(value instanceof JSONObject){JSONObject object=(JSONObject)value;List<String> keys=new ArrayList<>();object.keys().forEachRemaining(keys::add);Collections.sort(keys);StringBuilder s=new StringBuilder("{");for(String key:keys){if(s.length()>1)s.append(',');s.append(JSONObject.quote(key)).append(':').append(canonical(object.get(key)));}return s.append('}').toString();}if(value instanceof JSONArray){JSONArray rows=(JSONArray)value;StringBuilder s=new StringBuilder("[");for(int i=0;i<rows.length();i++){if(i>0)s.append(',');s.append(canonical(rows.get(i)));}return s.append(']').toString();}return value instanceof String?JSONObject.quote((String)value):String.valueOf(value);}
    static JSONObject business(JSONObject r)throws JSONException{JSONObject out=new JSONObject();Iterator<String> keys=r.keys();while(keys.hasNext()){String key=keys.next();if(!TRANSPORT.contains(key)&&!key.startsWith("tf_"))out.put(key,r.get(key));}return out;}
    static boolean same(JSONObject a,JSONObject b)throws JSONException{return canonical(business(a)).equals(canonical(business(b)));}
    static String localId(String table,String external){if(table.equals("task_type")){String kind=external.equals("type-ordinary")?"event":external.equals("type-long")?"project":external.equals("type-todo")?"task":null;if(kind!=null)return UUID.nameUUIDFromBytes(("dayflow:type:"+kind).getBytes(StandardCharsets.UTF_8)).toString();}try{return UUID.fromString(external).toString();}catch(Exception e){return UUID.nameUUIDFromBytes(("taskflow:"+table+":"+external).getBytes(StandardCharsets.UTF_8)).toString();}}
    static String externalId(JSONObject r){if(!r.optString("tf_id").isEmpty())return r.optString("tf_id");if(r.optString("kind").equals("type")&&r.optBoolean("system_type")){String base=r.optString("base_kind");return base.equals("project")?"type-long":base.equals("task")?"type-todo":"type-ordinary";}return r.optString("id");}
    static String table(JSONObject r){if(r.optString("kind").equals("type"))return "task_type";if(Arrays.asList("note","inbox").contains(r.optString("kind"))||!r.optString("series_id").isEmpty())return "dayflow_record";return "schedule";}
    private static String baseKind(String behavior){return behavior.equals("long")?"project":behavior.equals("todo")?"task":"event";}
    private static String behavior(String kind){return kind.equals("project")?"long":kind.equals("task")?"todo":"ordinary";}
    private static String iso(long milliseconds){return Instant.ofEpochMilli(milliseconds).atZone(ZoneId.systemDefault()).toLocalDateTime().toString();}
    private static long milliseconds(String iso){return LocalDateTime.parse(iso).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();}
    private static Object nullIfEmpty(String value){return value.isEmpty()?JSONObject.NULL:value;}
    private static JSONObject embedded(JSONObject row)throws JSONException{JSONObject attributes=row.optJSONObject("attributesJson");if(attributes!=null&&attributes.optJSONObject("dayflow")!=null)return new JSONObject(attributes.getJSONObject("dayflow").toString());String extra=row.optString("dayflowJson");return extra.isEmpty()?new JSONObject():new JSONObject(extra);}
    private static JSONObject foreignFields(JSONObject row)throws JSONException{JSONObject raw=new JSONObject(row.toString());raw.remove("dayflowJson");raw.remove("notes");JSONObject attributes=raw.optJSONObject("attributesJson");if(attributes!=null)attributes.remove("dayflow");return raw;}
    static JSONObject from(String table,String id,JSONObject row,Map<String,JSONObject> types)throws Exception{
        if(table.equals("dayflow_record")){JSONObject r=new JSONObject(row.getString("recordJson"));r.put("tf_id",id).put("tf_table",table);Data.validate(r);return r;}
        JSONObject saved=embedded(row);String kind;
        if(table.equals("task_type"))kind="type";else{JSONObject type=types.get(row.optString("typeId"));kind=baseKind(type==null?"ordinary":type.optString("baseBehavior"));if(saved.optString("kind").equals("course")&&kind.equals("event"))kind="course";}
        JSONObject r=Data.make(kind,row.optString(table.equals("task_type")?"name":"title")).put("tf_id",id).put("tf_table",table);for(Iterator<String> keys=saved.keys();keys.hasNext();){String key=keys.next();r.put(key,saved.get(key));}r.put("id",localId(table,id)).put("kind",kind).put("title",row.optString(table.equals("task_type")?"name":"title")).put("deleted",row.has("deletedAt")&&!row.isNull("deletedAt"));
        if(table.equals("task_type")){r.put("base_kind",baseKind(row.optString("baseBehavior"))).put("system_type",row.optBoolean("isSystem")).put("icon",row.optString("icon","")).put("color",row.optString("color","")).put("parent_id",row.isNull("parentId")?"":localId(table,row.optString("parentId"))).put("archived",row.has("archivedAt")&&!row.isNull("archivedAt"));if(!row.isNull("mergedIntoId")&&!row.optString("mergedIntoId").isEmpty())r.put("merged_into",localId(table,row.optString("mergedIntoId")));r.put("tf_raw",foreignFields(row));return r;}
        r.put("content",row.optString("notes","")).put("type_id",localId("task_type",row.optString("typeId"))).put("parent_id",row.isNull("parentId")?"":localId("schedule",row.optString("parentId"))).put("location",row.isNull("location")?"":row.optString("location"));String mode=row.optString("timeMode","undated");r.put("start_at","").put("end_at","").put("due_date","").put("all_day",mode.equals("allday"));
        if(mode.equals("timed")&&!row.isNull("startAt")){r.put("start_at",iso(row.getLong("startAt")));if(!row.isNull("endAt"))r.put("end_at",iso(row.getLong("endAt")));}
        else if(mode.equals("allday")&&!row.isNull("startDate")){LocalDate start=LocalDate.parse(row.getString("startDate"));r.put("start_at",start.atStartOfDay().toString()).put("end_at",(row.isNull("endDate")?start.plusDays(1):LocalDate.parse(row.getString("endDate"))).atStartOfDay().toString());}
        else if(!row.isNull("dueDate")&&!row.optString("dueDate").isEmpty())r.put("due_date",row.getString("dueDate"));else if(!row.isNull("dueAt"))r.put("due_date",Instant.ofEpochMilli(row.getLong("dueAt")).atZone(ZoneId.systemDefault()).toLocalDate().toString());
        String status=row.optString("status","planned");r.put("status",status).put("completed",status.equals("done")?Instant.ofEpochMilli(row.isNull("completedAt")?row.optLong("updatedAt",System.currentTimeMillis()):row.getLong("completedAt")).toString():"");JSONObject recurrence=row.optJSONObject("recurrenceJson");r.put("repeat","").put("recurrence",recurrence==null||recurrence.optString("kind").equals("none")?"":recurrence.optString("kind"));if(recurrence!=null&&recurrence.optJSONArray("weekdays")!=null)r.put("weekdays",recurrence.getJSONArray("weekdays"));
        JSONObject notification=row.optJSONObject("notificationJson");r.put("reminder",notification!=null&&notification.optBoolean("enabled"));if(notification!=null){JSONArray rules=notification.optJSONArray("rules");StringJoiner offsets=new StringJoiner(",");if(rules!=null)for(int i=0;i<Math.min(5,rules.length());i++){JSONObject rule=rules.optJSONObject(i);if(rule!=null&&rule.optInt("offsetMinutes",-10)<=0)offsets.add(Integer.toString(-rule.optInt("offsetMinutes",-10)));}if(offsets.length()>0)r.put("reminder_offsets",offsets.toString());}r.put("tf_raw",foreignFields(row));Data.validate(r);return r;
    }
    static JSONObject to(JSONObject r,Map<String,String> externalTypes,Map<String,String> externalSchedules)throws Exception{
        String table=table(r);if(table.equals("dayflow_record")){JSONObject metadata=new JSONObject(r.toString());metadata.remove("tf_raw");return new JSONObject().put("recordJson",metadata.toString());}JSONObject old=r.optJSONObject("tf_raw"),out=old==null?new JSONObject():new JSONObject(old.toString());long now=System.currentTimeMillis();out.remove("dayflowMovedTo");out.put("updatedAt",now).put("deletedAt",r.optBoolean("deleted")?now:JSONObject.NULL);if(!out.has("createdAt"))out.put("createdAt",now);
        if(table.equals("task_type")){out.put("key",out.optString("key",r.optBoolean("system_type")?behavior(r.optString("base_kind")):"dayflow-"+r.optString("id"))).put("name",r.optString("title")).put("icon",nullIfEmpty(r.optString("icon"))).put("color",nullIfEmpty(r.optString("color"))).put("parentId",r.optString("parent_id").isEmpty()?JSONObject.NULL:externalTypes.getOrDefault(r.optString("parent_id"),r.optString("parent_id"))).put("baseBehavior",behavior(r.optString("base_kind"))).put("isSystem",r.optBoolean("system_type")).put("archivedAt",r.optBoolean("archived")?now:JSONObject.NULL).put("mergedIntoId",r.optString("merged_into").isEmpty()?JSONObject.NULL:externalTypes.getOrDefault(r.optString("merged_into"),r.optString("merged_into"))).put("source",r.optBoolean("system_type")?"system":"user");if(!out.has("fieldSchemaJson"))out.put("fieldSchemaJson",new JSONArray());if(!out.has("sortOrder"))out.put("sortOrder",now);JSONObject metadata=new JSONObject(r.toString());metadata.remove("tf_raw");out.put("dayflowJson",metadata.toString());return out;}
        String kind=r.optString("kind"),fallback=kind.equals("project")?"type-long":kind.equals("task")?"type-todo":"type-ordinary";out.put("title",r.optString("title")).put("notes",r.optString("content")).put("typeId",externalTypes.getOrDefault(r.optString("type_id"),fallback)).put("parentId",r.optString("parent_id").isEmpty()?JSONObject.NULL:externalSchedules.getOrDefault(r.optString("parent_id"),r.optString("parent_id"))).put("location",nullIfEmpty(r.optString("location"))).put("status",PlanTime.cancelled(r)?"cancelled":r.optString("completed").isEmpty()?"planned":"done").put("completedAt",r.optString("completed").isEmpty()?JSONObject.NULL:Instant.parse(r.optString("completed")).toEpochMilli());
        boolean scheduled=!r.optString("start_at").isEmpty(),allDay=r.optBoolean("all_day");out.put("timeMode",scheduled?allDay?"allday":"timed":"undated").put("startAt",scheduled&&!allDay?milliseconds(r.optString("start_at")):JSONObject.NULL).put("endAt",scheduled&&!allDay?PlanTime.end(r).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli():JSONObject.NULL).put("startDate",scheduled&&allDay?r.optString("start_at").substring(0,10):JSONObject.NULL).put("endDate",scheduled&&allDay?PlanTime.end(r).toLocalDate().toString():JSONObject.NULL).put("dueDate",nullIfEmpty(r.optString("due_date"))).put("dueAt",JSONObject.NULL).put("tz",out.optString("tz",ZoneId.systemDefault().getId())).put("source",out.optString("source","user"));
        JSONObject recurrence=new JSONObject().put("kind",r.optString("recurrence").isEmpty()?"none":r.optString("recurrence"));if(r.optJSONArray("weekdays")!=null)recurrence.put("weekdays",r.optJSONArray("weekdays"));out.put("recurrenceJson",recurrence);JSONArray rules=new JSONArray();for(int minutes:PlanOptions.offsets(r))rules.put(new JSONObject().put("offsetMinutes",-minutes).put("channel","system"));out.put("notificationJson",new JSONObject().put("enabled",r.optBoolean("reminder")).put("rules",rules));JSONObject attributes=out.optJSONObject("attributesJson");if(attributes==null)attributes=new JSONObject();JSONObject embedded=new JSONObject(r.toString());embedded.remove("tf_raw");attributes.put("dayflow",embedded);out.put("attributesJson",attributes);if(!out.has("tagsJson"))out.put("tagsJson",new JSONArray());if(!out.has("sortOrder"))out.put("sortOrder",0);if(!out.has("externalUid"))out.put("externalUid",JSONObject.NULL);return out;
    }
}
